query catalogSubThemes($themeCode: String!, $classId: String, $subjectId: String, $practiceId: String, $sortVariantCode: String, $search: String, $classroomId: String, $isEducont: Boolean) {
  catalogSubThemes(
    themeCode: $themeCode
    classId: $classId
    subjectId: $subjectId
    practiceId: $practiceId
    sortVariantCode: $sortVariantCode
    search: $search
    classroomId: $classroomId
    isEducont: $isEducont
  ) {
    id
    theme {
      id
      classId
      subjectId
    }
    name
    number
    type
    iframeUrl
    code
    sortVariatns {
      code
    }
    studentStat {
      points
      isStarted
      isFinished
    }
    lastPracticeDate
    educontOverwriteId
  }
}
